/* eslint-disable @typescript-eslint/no-unused-vars */
import { ethers, BigNumber, Contract } from 'ethers'
import { TransactionRequest } from '@ethersproject/abstract-provider'

import {
  NumberLike,
  AddressLike,
  IActionOptions,
} from '../interfaces'
import { toAddress } from '../utils'
import { StandardBridgeAdapter } from './standard-bridge'
import {
  CrossChainMessenger,
} from '../cross-chain-messenger'
import { hexStringEquals } from '../utils/hex-strings'
import { Console } from '../utils/console'
import { estimateCrossDomainMessageFee } from '../l1-provider'
import { getContractInterface } from '../utils/contract-defs'

/**
 * Bridge adapter for the ETH bridge.
 */
export class ETHBridgeAdapter extends StandardBridgeAdapter {
  constructor(opts: {
    messenger: CrossChainMessenger
    l1Bridge: AddressLike
    l2Bridge: AddressLike
  }) {
    super(opts)
    this.messenger = opts.messenger

    let l1BridgeName = 'L1GatewayRouter',
      l2BridgeName = 'L2GatewayRouter'
    
    Console.log(
      'ETHBridgeAdapter',
      toAddress(
        opts.l1Bridge
      ),
      toAddress(
        opts.l2Bridge
      )
    )
    this.l1Bridge = new Contract(
      toAddress(
        opts.l1Bridge
      ),
      getContractInterface(l1BridgeName),
      this.messenger.l1Provider
    )
    this.l2Bridge = new Contract(
      toAddress(
        opts.l2Bridge
      ),
      getContractInterface(l2BridgeName),
      this.messenger.l2Provider
    )
  }
  
  public async approval(
    l1Token: AddressLike,
    l2Token: AddressLike,
    opts?: IActionOptions
  ): Promise<BigNumber> {
    throw new Error(`approval not necessary for ETH bridge`)
  }

  public async supportsTokenPair(
    l1Token: AddressLike,
    l2Token: AddressLike
  ): Promise<boolean> {
    // Only support ETH deposits and withdrawals.
    return (
      hexStringEquals(toAddress(l1Token), ethers.constants.AddressZero) &&
      hexStringEquals(toAddress(l2Token), ethers.constants.AddressZero)
    )
  }

  populateTransaction = {
    approve: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts?: IActionOptions
    ): Promise<never> => {
      throw new Error(`approvals not necessary for ETH bridge`)
    },

    deposit: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts: IActionOptions
    ): Promise<TransactionRequest> => {
      if (!(await this.supportsTokenPair(l1Token, l2Token))) {
        throw new Error(`token pair not supported by bridge`)
      }
      const gasLimit = BigInt(opts?.overrides?.gasLimit?.toString() || '2000000')

      const gasFee = await estimateCrossDomainMessageFee(
        this.messenger.l1Provider,
        this.messenger.contracts.l1?.L1MessageQueueWithGasPriceOracle?.address,
      )
      Console.log('estimateCrossDomainMessageFee gasFee.mul(gasLimit).toBigInt()', gasFee.toString(), gasLimit.toString(), gasFee.mul(gasLimit).toBigInt());
      
      const options = {
        value: BigInt(amount as string) + gasFee.mul(gasLimit).toBigInt(),
      }

      Console.log(`depositing this.l1Bridge ETH`, this.l1Bridge, gasFee, gasLimit)
      
      if (opts?.recipient === undefined) {
        return this.l1Bridge.populateTransaction['depositETH(uint256,uint256)'](
          amount,
          gasLimit,
          options
        )
      } else {
        return this.l1Bridge.populateTransaction[
          'depositETH(address,uint256,uint256)'
        ](toAddress(opts.recipient || opts.from), amount, gasLimit, options)
      }
    },

    withdraw: async (
      l1Token: AddressLike,
      l2Token: AddressLike,
      amount: NumberLike,
      opts: IActionOptions
    ): Promise<TransactionRequest> => {
      if (!(await this.supportsTokenPair(l1Token, l2Token))) {
        throw new Error(`token pair not supported by bridge`)
      }
      const gasLimit = BigInt(
        (opts?.overrides?.gasLimit || '300000').toString()
      )
      const options = {
        // ...omit(opts?.overrides || {}, 'value'),
        value: BigInt(amount as string),
        gasLimit,
      }
      Console.log(`withdraw ${amount} ETH`, gasLimit, options)
      if (opts?.recipient === undefined) {
        return this.l2Bridge.populateTransaction[
          'withdrawETH(uint256,uint256)'
        ](amount, gasLimit, options)
      } else {
        return this.l2Bridge.populateTransaction[
          'withdrawETH(address,uint256,uint256)'
        ](toAddress(opts.recipient || opts.from), amount, gasLimit, options)
      }
    },
  }
}
